bool isTrackRowOverlappingViewport(String playingPath) {
  // Missing contexts means the row isn't mounted yet — treat that as
  // “outside the visible region” so the action is enabled.
  final listBox =
      listViewKey.currentContext?.findRenderObject() as RenderBox?;
  final rowBox =
      rowKeys[playingPath]?.currentContext?.findRenderObject() as RenderBox?;
  if (listBox == null || rowBox == null) return false;

  final listRect = listBox.localToGlobal(Offset.zero) & listBox.size;
  final rowRect = rowBox.localToGlobal(Offset.zero) & rowBox.size;
  return rowRect.overlaps(listRect);
}

edits.newText:
bool isTrackRowOverlappingViewport(_BrowserTheme t, String playingPath) {
  // Use ScrollController + known per-row heights instead of RenderBox
  // intersection: for reverse:true + bottom anchoring, it’s the most
  // stable visibility signal for enabling/disabling the action.
  if (!scroll.hasClients) return false;

  final index = ctrl.tracks.indexWhere((it) => it.path == playingPath);
  if (index < 0) return false;

  final hasUp = ctrl.currentPath != null ? 1 : 0;
  final childIndex = hasUp + (ctrl.tracks.length - 1 - index);

  final rowHeight = t.geometry.rowHeight;
  final viewport = scroll.position.viewportDimension;
  final scrollOffset = scroll.position.pixels;

  // In a normal scrollable, viewport-top = scrollOffset and
  // rowTopInViewport = rowTopAbsolute - scrollOffset. scrollToTrack’s
  // fallback uses the same coordinate mapping (childIndex*rowHeight).
  final rowTopInViewport = childIndex * rowHeight - scrollOffset;
  final rowBottomInViewport = rowTopInViewport + rowHeight;

  return rowBottomInViewport > 0 && rowTopInViewport < viewport;
}

